## Submitted testbench
```systemverilog
module tb;

  // --------------------------------------------------------------
  // Clock and reset
  // --------------------------------------------------------------
  localparam int CLK_PERIOD = 8; // 125 MHz
  logic clk = 0;
  always #(CLK_PERIOD/2) clk = ~clk;

  logic rst = 0;
  initial begin
    #100 rst = 1;
    #100 rst = 0;
    #100;
  end

  // --------------------------------------------------------------
  // DUT interface signals
  // --------------------------------------------------------------
  logic rxd = 1'b1;
  logic [15:0] prescale = 16'd5;

  // AXI‑Stream output from DUT
  logic [7:0] m_axis_tdata;
  logic       m_axis_tvalid;

  // Dummy status outputs (unused)
  logic busy;
  logic overrun_error;
  logic frame_error;

  // --------------------------------------------------------------
  // DUT instantiation (m_axis_tready held low)
  // --------------------------------------------------------------
  uart_rx #(.DATA_WIDTH(8)) dut (
    .clk          (clk),
    .rst          (rst),
    .m_axis_tdata (m_axis_tdata),
    .m_axis_tvalid(m_axis_tvalid),
    .m_axis_tready(1'b0),   // always low
    .rxd          (rxd),
    .busy         (busy),
    .overrun_error(overrun_error),
    .frame_error  (frame_error),
    .prescale     (prescale)
  );

  // --------------------------------------------------------------
  // Helper tasks
  // --------------------------------------------------------------
  task automatic wait_cycles(input int n);
    repeat (n) @(negedge clk);
  endtask

  // Send a byte on rxd (8N1, LSB first) using the current prescale value
  task automatic uart_send_byte(input byte unsigned b);
    int bit_clks = int'(prescale) * 8;
    // start bit
    rxd = 1'b0; wait_cycles(bit_clks);
    // data bits
    for (int i = 0; i < 8; i++) begin
      rxd = b[i];
      wait_cycles(bit_clks);
    end
    // stop bit
    rxd = 1'b1;
    wait_cycles(bit_clks);
  endtask

  // --------------------------------------------------------------
  // Main stimulus
  // --------------------------------------------------------------
  initial begin
    // Wait for reset release
    #5000;

    // Send first arbitrary byte (e.g., 0x3C)
    uart_send_byte(8'h3C);
    // Immediately send the target byte 0x5A (the word captured on double overrun)
    uart_send_byte(8'h5A);

    // Allow enough time for the coverage property to be evaluated
    repeat (2000) @(negedge clk);

    $display("Testbench finished – coverage point should have been hit");
    $finish;
  end

endmodule
```

